WITH cleaned AS (SELECT id, store_id, status, channel, discount, shipping_fee, LOWER(status) AS status_lower, COALESCE(channel, 'UNKNOWN') AS channel_filled FROM orders WHERE order_date >= TO_DATE('2023-07-06') AND store_id IS NOT NULL) SELECT id, status, channel, discount, status_lower, channel_filled, LEAD(shipping_fee, 1) OVER (PARTITION BY store_id ORDER BY discount, id) AS next_shipping_fee, NTILE(3) OVER (PARTITION BY channel ORDER BY discount DESC, id) AS discount_bucket FROM cleaned;
